-- 基线：本站账号与 e 站图集的全部表。
-- 写成幂等的形式：在已有这些表的库上什么也不改，只由迁移器登记为已执行；在空库上则建出同样的结构。
-- drizzle-kit 生成的版本不幂等，这里在它的基础上加了 IF NOT EXISTS，外键按名字查过没有才加；
-- 同目录的 snapshot.json 是 drizzle-kit 1.0 从表结构生成的原样，仍描述同一份结构，后续迁移照常生成。
CREATE TABLE IF NOT EXISTS "users" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "users_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"username" text NOT NULL,
	"password_hash" text NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp (3) with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
