	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "eh_credentials_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint NOT NULL,
	"ipb_member_id" text NOT NULL,
	"ipb_pass_hash" text NOT NULL,
	"igneous" text NOT NULL,
	"has_ex_access" boolean NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp (3) with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "eh_preferences" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "eh_preferences_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint NOT NULL,
	"categories" text[] DEFAULT '{}' NOT NULL,
	"min_rating" integer,
	"reader_interval" integer DEFAULT 5 NOT NULL,
	"search_history" text[] DEFAULT '{}' NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "eh_preferences_min_rating_check" CHECK ("eh_preferences"."min_rating" BETWEEN 2 AND 5),
	CONSTRAINT "eh_preferences_reader_interval_check" CHECK ("eh_preferences"."reader_interval" BETWEEN 1 AND 20),
	CONSTRAINT "eh_preferences_search_history_check" CHECK (CARDINALITY("eh_preferences"."search_history") <= 10)
);
--> statement-breakpoint
