DO $$
DECLARE
    foreign_keys CONSTANT text[][] := ARRAY[
        ['eh_credentials', 'eh_credentials_user_id_fkey', 'FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action'],
        ['eh_preferences', 'eh_preferences_user_id_fkey', 'FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action'],
        ['eh_reading_progress', 'eh_reading_progress_user_id_fkey', 'FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action']
    ];
    item text[];
BEGIN
    FOREACH item SLICE 1 IN ARRAY foreign_keys LOOP
        IF NOT EXISTS (
            SELECT 1 FROM pg_constraint
            WHERE conrelid = format('public.%I', item[1])::regclass AND conname = item[2]
        ) THEN
            EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I %s', item[1], item[2], item[3]);
        END IF;
    END LOOP;
END
$$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "users_username_key" ON "users" USING btree ("username");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "eh_credentials_user_id_key" ON "eh_credentials" USING btree ("user_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "eh_preferences_user_id_key" ON "eh_preferences" USING btree ("user_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "eh_reading_progress_user_gid_key" ON "eh_reading_progress" USING btree ("user_id","gid");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "eh_reading_progress_user_recent_idx" ON "eh_reading_progress" USING btree ("user_id","updated_at" DESC NULLS FIRST,"gid" DESC NULLS FIRST);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "eh_tag_translations_namespace_raw_key" ON "eh_tag_translations" USING btree ("namespace","raw");